import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Catalog Attributes — Datagrid Listing","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-attributes-list","title":"List Catalog Attributes (Datagrid)","description":"Paginated, filterable, sortable attribute list mirroring the Bagisto admin Catalog → Attributes datagrid. Returns the standard `{ data, meta }` envelope.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/attributes?per_page=10&page=1&type=select&sort=id&order=desc\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"per_page=10&page=1&type=select&sort=id&order=desc\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"sku\\",\\n      \\"type\\": \\"text\\",\\n      \\"adminName\\": \\"SKU\\",\\n      \\"isRequired\\": 1,\\n      \\"isUnique\\": 1,\\n      \\"valuePerLocale\\": 0,\\n      \\"valuePerChannel\\": 0,\\n      \\"isFilterable\\": 0,\\n      \\"isConfigurable\\": 0,\\n      \\"isVisibleOnFront\\": 0,\\n      \\"isUserDefined\\": 0,\\n      \\"swatchType\\": null,\\n      \\"position\\": 1,\\n      \\"locale\\": \\"en\\",\\n      \\"createdAt\\": \\"2024-01-01T00:00:00+00:00\\",\\n      \\"updatedAt\\": \\"2024-01-01T00:00:00+00:00\\",\\n      \\"translations\\": null,\\n      \\"options\\": null,\\n      \\"validation\\": null,\\n      \\"defaultValue\\": null\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 5,\\n    \\"total\\": 47,\\n    \\"from\\": 1,\\n    \\"to\\": 10\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/attributes/attributes-listing.md","filePath":"api/rest-api/admin/catalog/attributes/attributes-listing.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/admin/catalog/attributes/attributes-listing.md"};function i(n,t,c,s,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attributes-—-datagrid-listing" tabindex="-1">Catalog Attributes — Datagrid Listing <a class="header-anchor" href="#catalog-attributes-—-datagrid-listing" aria-label="Permalink to &quot;Catalog Attributes — Datagrid Listing&quot;">​</a></h1><p>Paginated, filterable, and sortable attribute list that mirrors the Bagisto admin <strong>Catalog → Attributes</strong> datagrid 1:1. This is the authoritative attribute-management listing for the admin API — same columns, same filters, and the same sort options used by the datagrid.</p><p>For attribute types, options, and the configurable and filterable flags, see the <a href="/api/rest-api/admin/catalog/attributes/">Attributes overview</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/attributes</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number (1-based, default <code>1</code>)</td><td><code>1</code></td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>id</code></td><td>string</td><td>Filter by attribute ID — single integer or comma-separated list (e.g. <code>&quot;1&quot;</code> or <code>&quot;1,2&quot;</code>)</td><td><code>1</code></td></tr><tr><td><code>code</code></td><td>string</td><td>Partial attribute code match (SQL <code>LIKE %value%</code>)</td><td><code>color</code></td></tr><tr><td><code>type</code></td><td>string</td><td>Exact attribute type filter</td><td><code>select</code></td></tr><tr><td><code>admin_name</code></td><td>string</td><td>Partial admin name match (SQL <code>LIKE %value%</code>)</td><td><code>Color</code></td></tr><tr><td><code>is_required</code></td><td>integer</td><td>Filter by is_required: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_unique</code></td><td>integer</td><td>Filter by is_unique: <code>0</code> = no, <code>1</code> = yes</td><td><code>0</code></td></tr><tr><td><code>is_filterable</code></td><td>integer</td><td>Filter by is_filterable: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_configurable</code></td><td>integer</td><td>Filter by is_configurable: <code>0</code> = no, <code>1</code> = yes</td><td><code>0</code></td></tr><tr><td><code>is_visible_on_front</code></td><td>integer</td><td>Filter by is_visible_on_front: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>is_user_defined</code></td><td>integer</td><td>Filter by is_user_defined: <code>0</code> = no, <code>1</code> = yes</td><td><code>1</code></td></tr><tr><td><code>value_per_locale</code></td><td>integer</td><td>Filter by value_per_locale: <code>0</code> = no, <code>1</code> = yes</td><td><code>0</code></td></tr><tr><td><code>value_per_channel</code></td><td>integer</td><td>Filter by value_per_channel: <code>0</code> = no, <code>1</code> = yes</td><td><code>0</code></td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code for translation resolution (default: app locale)</td><td><code>en</code></td></tr><tr><td><code>sort</code></td><td>string</td><td>Column to sort by (see Sorting section below)</td><td><code>id</code></td></tr><tr><td><code>order</code></td><td>string</td><td>Sort direction: <code>asc</code> or <code>desc</code> (default <code>desc</code>)</td><td><code>desc</code></td></tr></tbody></table><p><strong>Valid <code>type</code> values:</strong> <code>text</code>, <code>textarea</code>, <code>price</code>, <code>boolean</code>, <code>select</code>, <code>multiselect</code>, <code>datetime</code>, <code>date</code>, <code>image</code>, <code>file</code>, <code>checkbox</code></p><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>Responses use the standard admin <code>{ data, meta }</code> envelope.</p><h3 id="meta-object" tabindex="-1"><code>meta</code> object <a class="header-anchor" href="#meta-object" aria-label="Permalink to &quot;`meta` object&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>currentPage</code></td><td>integer</td><td>Current page number (1-based)</td></tr><tr><td><code>perPage</code></td><td>integer</td><td>Number of items on this page</td></tr><tr><td><code>lastPage</code></td><td>integer</td><td>Total number of pages</td></tr><tr><td><code>total</code></td><td>integer</td><td>Total matching attributes</td></tr><tr><td><code>from</code></td><td>integer</td><td>1-based index of the first item on this page</td></tr><tr><td><code>to</code></td><td>integer</td><td>1-based index of the last item on this page</td></tr></tbody></table><h3 id="row-fields-data" tabindex="-1">Row fields (<code>data[]</code>) <a class="header-anchor" href="#row-fields-data" aria-label="Permalink to &quot;Row fields (`data[]`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Attribute code (e.g. <code>color</code>, <code>size</code>)</td></tr><tr><td><code>type</code></td><td>string</td><td>Attribute type (e.g. <code>select</code>, <code>text</code>, <code>boolean</code>)</td></tr><tr><td><code>adminName</code></td><td>string</td><td>Internal admin-facing label</td></tr><tr><td><code>isRequired</code></td><td>integer</td><td><code>1</code> = required on product forms, <code>0</code> = optional</td></tr><tr><td><code>isUnique</code></td><td>integer</td><td><code>1</code> = value must be unique across products</td></tr><tr><td><code>valuePerLocale</code></td><td>integer</td><td><code>1</code> = separate value per store locale</td></tr><tr><td><code>valuePerChannel</code></td><td>integer</td><td><code>1</code> = separate value per channel</td></tr><tr><td><code>isFilterable</code></td><td>integer</td><td><code>1</code> = attribute appears in layered navigation filters</td></tr><tr><td><code>isConfigurable</code></td><td>integer</td><td><code>1</code> = used as a configurable variant axis</td></tr><tr><td><code>isVisibleOnFront</code></td><td>integer</td><td><code>1</code> = shown on the product page storefront</td></tr><tr><td><code>isUserDefined</code></td><td>integer</td><td><code>1</code> = created by an admin user (not a system attribute)</td></tr><tr><td><code>swatchType</code></td><td>string|null</td><td>Swatch rendering mode (<code>color</code>, <code>image</code>, <code>text</code>); <code>null</code> for non-swatch types</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order position</td></tr><tr><td><code>locale</code></td><td>string|null</td><td>Locale code used for name resolution</td></tr><tr><td><code>createdAt</code></td><td>string|null</td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string|null</td><td>ISO 8601 last-update timestamp</td></tr><tr><td><code>translations</code></td><td>null</td><td>Always <code>null</code> in list responses — full translations are available via the detail endpoint <code>GET /api/admin/catalog/attributes/{id}</code></td></tr><tr><td><code>options</code></td><td>null</td><td>Always <code>null</code> in list responses — option data is available via the detail endpoint</td></tr><tr><td><code>validation</code></td><td>null</td><td>Always <code>null</code> in list responses — available via the detail endpoint</td></tr><tr><td><code>defaultValue</code></td><td>null</td><td>Always <code>null</code> in list responses — available via the detail endpoint</td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter form</th><th>Example</th></tr></thead><tbody><tr><td>Separate <code>sort</code> + <code>order</code> params</td><td><code>?sort=id&amp;order=desc</code></td></tr></tbody></table><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Attribute ID (default)</td></tr><tr><td><code>code</code></td><td>Attribute code</td></tr><tr><td><code>admin_name</code></td><td>Admin label</td></tr><tr><td><code>type</code></td><td>Attribute type</td></tr><tr><td><code>position</code></td><td>Display order position</td></tr></tbody></table><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><ul><li>Default page size: <strong>10</strong> items</li><li>Maximum page size: <strong>50</strong> items</li><li>Use <code>?page=N</code> for page navigation and <code>?per_page=N</code> to control page size</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing, expired, or revoked admin Bearer token</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token</td></tr></tbody></table><p><strong>Unknown filter parameters</strong> are silently ignored — no error is returned.</p><h2 id="fields-that-stay-null-on-the-listing" tabindex="-1">Fields That Stay Null on the Listing <a class="header-anchor" href="#fields-that-stay-null-on-the-listing" aria-label="Permalink to &quot;Fields That Stay Null on the Listing&quot;">​</a></h2><p><code>translations</code>, <code>options</code>, <code>validation</code>, <code>defaultValue</code>, <code>isComparable</code>, <code>enableWysiwyg</code>, and <code>regex</code> are present on every row but always <code>null</code>. All resolve only on <a href="/api/rest-api/admin/catalog/attributes/attributes-detail.html"><code>GET /api/admin/catalog/attributes/{id}</code></a>, which loads every locale translation and, for option types, all options with their own translations.</p><h2 id="behaviour-worth-knowing" tabindex="-1">Behaviour Worth Knowing <a class="header-anchor" href="#behaviour-worth-knowing" aria-label="Permalink to &quot;Behaviour Worth Knowing&quot;">​</a></h2><ul><li><strong>The boolean flags are integers</strong>, <code>0</code> or <code>1</code>, not booleans.</li><li><strong>System attributes are included.</strong> The listing returns both Bagisto&#39;s built-in attributes and admin-created ones. Pass <code>?is_user_defined=1</code> for admin-created only, or <code>?is_user_defined=0</code> for system only — worth knowing because system attributes cannot be deleted.</li><li><strong><code>adminName</code> is not locale-aware.</strong> It is the internal label set when the attribute was created. <code>?locale</code> selects which translation row resolves the display name, falling back to <code>adminName</code> when the requested locale has no row.</li><li><strong><code>swatchType</code> stays <code>null</code> on a non-swatch attribute</strong> rather than carrying a default.</li><li><code>per_page</code> caps at <strong>50</strong>; a value of <code>0</code> or less falls back to <strong>10</strong>.</li></ul>',27)]))}const p=e(r,[["render",i]]);export{g as __pageData,p as default};
